static const Id128 MVS_MISSION=id_from_seed("GENESIS-MVS-001-CANARY");static const Id128 MVS_TASK=id_from_seed("GENESIS-MVS-001-WRITE");static const Id128 MVS_CORR=id_from_seed("GENESIS-MVS-001-CORR");static constexpr char OLD_TEXT[]="FUSE-GENESIS-OLD-V1";static constexpr char NEW_TEXT[]="FUSE-GENESIS-NEW-V1";
static Status event_payload(EventType e,const Digest256*task,const Digest256*nonce,const Id128*permit,const Digest256*idempotency,Buffer*out){FcbWriter w{};auto st=fcb_begin(&w,(u16)(0x4000+(u32)e),0);if(st!=Status::Ok)return st;if(task)fcb_put_bytes(&w,1,FcbType::DIGEST256,{task->bytes.data(),32});if(nonce)fcb_put_bytes(&w,2,FcbType::DIGEST256,{nonce->bytes.data(),32});if(permit)fcb_put_bytes(&w,3,FcbType::BYTES,{permit->bytes.data(),16});if(idempotency)fcb_put_bytes(&w,4,FcbType::DIGEST256,{idempotency->bytes.data(),32});return fcb_finish(&w,out,nullptr);}
Status runtime_open(const std::wstring&root,Runtime*out){if(!out)return Status::InvalidArgument;*out=Runtime{};out->root=root;out->state_root=(std::filesystem::path(root)/L"state").wstring();out->workspace_root=(std::filesystem::path(root)/L"workspace").wstring();auto objects=(std::filesystem::path(root)/L"objects").wstring();ensure_directory(out->state_root);ensure_directory(out->workspace_root);ensure_directory(objects);auto st=journal_writer_open(out->state_root,&out->journal);if(st!=Status::Ok)return st;if((st=object_store_open(objects,&out->objects))!=Status::Ok)return st;if((st=registry_initialize(&out->registry))!=Status::Ok)return st;if((st=register_root(1,out->workspace_root,true,true,&out->workspace))!=Status::Ok)return st;return identity_open_or_create(&out->identity,L"FUSE-GENESIS-MVS-P256-V1");}
void runtime_close(Runtime*r){if(r)identity_close(&r->identity);}Status task_digest(const TaskEnvelope*t,Digest256*out){if(!t||!out)return Status::InvalidArgument;FcbWriter w{};fcb_begin(&w,0x4101,0);fcb_put_bytes(&w,1,FcbType::BYTES,{t->mission_id.bytes.data(),16});fcb_put_u64(&w,2,t->mission_version);fcb_put_bytes(&w,3,FcbType::BYTES,{t->task_id.bytes.data(),16});fcb_put_u64(&w,4,t->capability_id);fcb_put_bytes(&w,5,FcbType::DIGEST256,{t->registry_root.bytes.data(),32});fcb_put_bytes(&w,6,FcbType::DIGEST256,{t->canonical_arguments_hash.bytes.data(),32});fcb_put_bytes(&w,7,FcbType::DIGEST256,{t->nonce.bytes.data(),32});fcb_put_bytes(&w,8,FcbType::DIGEST256,{t->idempotency_key.bytes.data(),32});Buffer b;return fcb_finish(&w,&b,out);}Status append_event(Runtime*r,const Id128&mission,u64 mission_version,EventType e,ByteSpan p){if(!r)return Status::InvalidArgument;return journal_append(&r->journal,&mission,mission_version,(u32)e,p,nullptr);}
struct ProjectionContext{Id128 mission_id{};u64 mission_version{};Digest256 task_digest{};TaskSecurityProjection*out{};};
static Status projection_cb(const JournalRecordView*v,void*ctxv){auto*ctx=(ProjectionContext*)ctxv;if(v->mission_id!=ctx->mission_id||v->mission_version!=ctx->mission_version)return Status::Ok;ByteSpan task{};if(fcb_get_bytes(v->payload,1,&task)!=Status::Ok||task.size!=32||!bytes_equal(task.data,ctx->task_digest.bytes.data(),32))return Status::Ok;auto*p=ctx->out;ByteSpan nonce{},permit{},idem{};fcb_get_bytes(v->payload,2,&nonce);fcb_get_bytes(v->payload,3,&permit);fcb_get_bytes(v->payload,4,&idem);if(nonce.size==32)bytes_copy(p->nonce.bytes.data(),nonce.data,32);if(permit.size==16)bytes_copy(p->permit_id.bytes.data(),permit.data,16);if(idem.size==32)bytes_copy(p->idempotency_key.bytes.data(),idem.data,32);switch((EventType)v->event_type){case EventType::MISSION_CREATED:p->mission_created=true;break;case EventType::TASK_RECEIVED:p->task_received=true;break;case EventType::TASK_VALIDATED:p->task_validated=true;break;case EventType::NONCE_CLAIMED:p->nonce_claimed=true;break;case EventType::IDEMPOTENCY_CLAIMED:p->idempotency_claimed=true;break;case EventType::ACTION_PREPARED:p->action_prepared=true;break;case EventType::PERMIT_ISSUED:p->permit_issued=true;break;case EventType::PERMIT_CONSUMED:p->permit_consumed=true;break;case EventType::EXECUTION_STARTED:p->execution_started=true;break;case EventType::EFFECT_RECONCILING:p->effect_reconciling=true;break;case EventType::EFFECT_OBSERVED:p->effect_observed=true;break;case EventType::RESULT_OBSERVED:p->result_observed=true;break;case EventType::RESULT_ATTESTED:p->result_attested=true;break;case EventType::TASK_PROVEN:p->task_proven=true;break;case EventType::MISSION_COMPLETE_VERIFIED:p->mission_complete=true;break;default:break;}return Status::Ok;}
Status project_task(Runtime*r,const Id128&mission,u64 mission_version,const Digest256&task,TaskSecurityProjection*out){if(!r||!out)return Status::InvalidArgument;*out=TaskSecurityProjection{};out->mission_id=mission;out->mission_version=mission_version;out->task_digest=task;ProjectionContext ctx{mission,mission_version,task,out};return journal_replay_all(r->state_root,projection_cb,&ctx);}
struct DigestSeenContext{EventType event_type{};u32 field_id{};Digest256 target{};bool found{};};
static Status digest_seen_cb(const JournalRecordView*v,void*ctxv){auto*ctx=(DigestSeenContext*)ctxv;if((EventType)v->event_type!=ctx->event_type)return Status::Ok;ByteSpan b{};if(fcb_get_bytes(v->payload,ctx->field_id,&b)==Status::Ok&&b.size==32&&bytes_equal(b.data,ctx->target.bytes.data(),32))ctx->found=true;return Status::Ok;}
static Status digest_seen(Runtime*r,EventType type,u32 field,const Digest256&target,bool*out){if(!r||!out)return Status::InvalidArgument;DigestSeenContext ctx{type,field,target,false};auto st=journal_replay_all(r->state_root,digest_seen_cb,&ctx);if(st==Status::Ok)*out=ctx.found;return st;}
Status nonce_seen(Runtime*r,const Digest256&nonce,bool*out){return digest_seen(r,EventType::NONCE_CLAIMED,2,nonce,out);}Status nonce_claim(Runtime*r,const Id128&mission,u64 mission_version,const Digest256&task,const Digest256&nonce){bool seen=false;auto st=nonce_seen(r,nonce,&seen);if(st!=Status::Ok)return st;if(seen)return Status::NonceReplay;Buffer ev;if((st=event_payload(EventType::NONCE_CLAIMED,&task,&nonce,nullptr,nullptr,&ev))!=Status::Ok)return st;return append_event(r,mission,mission_version,EventType::NONCE_CLAIMED,{ev.data(),(u64)ev.size()});}
Status idempotency_seen(Runtime*r,const Digest256&key,bool*out){return digest_seen(r,EventType::IDEMPOTENCY_CLAIMED,4,key,out);}Status idempotency_claim(Runtime*r,const Id128&mission,u64 mission_version,const Digest256&task,const Digest256&key){bool seen=false;auto st=idempotency_seen(r,key,&seen);if(st!=Status::Ok)return st;if(seen)return Status::IdempotencyReplay;Buffer ev;if((st=event_payload(EventType::IDEMPOTENCY_CLAIMED,&task,nullptr,nullptr,&key,&ev))!=Status::Ok)return st;return append_event(r,mission,mission_version,EventType::IDEMPOTENCY_CLAIMED,{ev.data(),(u64)ev.size()});}
Status permit_id_for(const PreparedAction*a,Id128*out){if(!a||!out)return Status::InvalidArgument;static constexpr char PERMIT_DOMAIN_TAG[]="FUSE:PERMIT:1";FcbWriter w{};auto st=fcb_begin(&w,0x4301,0);if(st!=Status::Ok)return st;fcb_put_bytes(&w,1,FcbType::UTF8,{(const u8*)PERMIT_DOMAIN_TAG,sizeof(PERMIT_DOMAIN_TAG)-1});fcb_put_bytes(&w,2,FcbType::DIGEST256,{a->task_digest.bytes.data(),32});fcb_put_bytes(&w,3,FcbType::DIGEST256,{a->effect_id.bytes.data(),32});fcb_put_bytes(&w,4,FcbType::DIGEST256,{a->prepared_digest.bytes.data(),32});Buffer b;Digest256 d{};if((st=fcb_finish(&w,&b,&d))!=Status::Ok)return st;bytes_copy(out->bytes.data(),d.bytes.data(),16);return Status::Ok;}
