static Status permit_seen_cb(const JournalRecordView*v,void*ctxv){auto*ctx=(PermitSeenContext*)ctxv;if((EventType)v->event_type!=ctx->event_type)return Status::Ok;ByteSpan b{};if(fcb_get_bytes(v->payload,3,&b)==Status::Ok&&b.size==16&&bytes_equal(b.data,ctx->target.bytes.data(),16))ctx->found=true;return Status::Ok;}
